function getFileVersion (filename) {
    var extension = getFileExtension(filename);
    if (extension == ".msi") {
        extension = "MSI";
    } else if (extension == ".exe") {
        extension = "EXE";
    }
    var version;
    if (!isValidAndNotEmpty(extension)) {
        version = appExternal.getFileVersion(extension, filename);
    }
    return version;
}

function renderComponents(filter, componentNames, isDisbale, disableArch, defaultBy64){
    for (var i = 0; i < filter.length; ++i) {
        var componentBox = $("[name='component" + filter[i] + "']");
        var subcomponentBox = $(".sub_component_" + filter[i]);
        var componentName = componentNames[filter[i]];
        var disable = "";
        if(isDisbale){
            disable = "disabled='disabled'";
        }
        for(var key in componentName){
            var name = "subcomponent" + filter[i];
            if (!isDisbale) {
                if (componentName[key]["mustSelect"]) {
                    disable = "disabled='disabled'";
                } else {
                    disable = "";
                }
            }
            if (!disableArch) {
                if (!defaultBy64 || filter[i] == "64") {
                    componentBox.prop("checked", true);
                    subcomponentBox.append("<input type='checkbox' class='vertical_align' name='" + name + "' id='" + key + "' checked='true' " + disable + "><label for='" + key +
                        "' class='vertical_align'>" + componentName[key]["name"] + "</label>");
                } else {
                    subcomponentBox.append("<input type='checkbox' class='vertical_align' name='" + name + "' id='" + key + "' " + disable + "><label for='" + key +
                        "' class='vertical_align'>" + componentName[key]["name"] + "</label>");
                }
            } else {
                componentBox.prop("checked", true);
                subcomponentBox.append("<input type='checkbox' class='vertical_align' name='" + name + "' id='" + key + "' checked='true' " + disable + "><label for='" + key +
                    "' class='vertical_align'>" + componentName[key]["name"] + "</label>");
            }
            subcomponentBox.append("<br/>");
        }
    }
}

