function getInstallSize(isSkipCheck){
    var total = 0;
    var sku = getSKU();
    for (var j = 0; j < os.length; ++j) {
        for (var i = 0; i < Components.length; ++i) {
            var component = Components[i];
            if (component["sku"] == sku && ((component["type"] & types[j]) != 0 || (component["type"] & ComponentType.Prerequiste) != 0)) {
                if (isISO || appExternal.getProperty(component["name"] + os[j]) == "true") { // the component has been downloaded
                    if (isSkipCheck) {
                        var reg = component["registry"];
                        if (Jobs.getDataFromRegistry(reg)) {
                            continue;
                        }
                    }
                    var files = component["files"];
                    for (var f = 0; f < files.length; ++f) {
                        total += files[f]["installSize"];
                    }
                }
            }
        }
    }
    return total;
}

